INSERT INTO offerings (type, slug, title, short_title, icon, summary, hero_text, quote, features, expertise_title, expertise_text, tech, meta_title, meta_description, sort_order) VALUES
('service', 'web-development', 'Web & Desktop App Development', 'Web Development', 'monitor',
 'Custom websites, web portals and desktop applications built around how your business really works, from a simple company site to a full enterprise system.',
 'Fast, secure and scalable web and desktop applications, planned with you and built by one dedicated team.',
 'Custom web solutions that grow with you',
 'Progressive Web Apps | Installable web apps that load fast, work offline and feel like native apps on any device.\nEnterprise Web Apps | Role-based systems for operations, finance and HR that replace spreadsheets and manual work.\nCustomer Portals | Secure self-service areas where your customers log in, track orders, pay invoices and get support.\nE-commerce Platforms | Online stores with smooth checkout, payment gateways, inventory sync and order tracking.\nSaaS Products | Multi-tenant platforms with subscriptions, billing, dashboards and admin tools.\nDesktop Applications | Cross-platform desktop tools for Windows, macOS and Linux built with Electron or .NET.',
 'Built for speed and security',
 'Every web project starts with a clear plan and clean architecture. We follow modern coding standards, write automated tests and run security checks before each release, so your app stays fast and safe as it grows.',
 'PHP, Laravel, Node.js, React, Next.js, Vue, Angular, MySQL, PostgreSQL, Electron',
 'Web & Desktop App Development Services | AivraSol',
 'Custom web apps, portals, SaaS products and desktop software built by AivraSol. Fast, secure and scalable. Get a free consultation.', 1),

('service', 'mobile-app-development', 'Mobile App Development', 'Mobile App', 'phone',
 'Native and cross-platform mobile apps for iOS and Android, from the first prototype to App Store and Google Play launch.',
 'Beautiful, reliable mobile apps that your users enjoy and your team can grow.',
 'Mobile apps people love to use',
 'iOS App Development | Native Swift apps that follow Apple design rules and pass App Store review smoothly.\nAndroid App Development | Kotlin apps tuned for the wide range of Android phones and tablets.\nCross-Platform Apps | One Flutter or React Native codebase for both platforms to save time and budget.\nApp Store Launch | Store listings, screenshots, review guidance and release management handled for you.\nAPIs and Backends | Secure APIs, push notifications, payments and real-time features behind your app.\nMaintenance and Updates | OS updates, crash monitoring and new features after launch.',
 'From idea to app store',
 'We design every screen with real users in mind, test on real devices, and set up crash reporting and analytics from day one, so you can see how people use your app and improve it with confidence.',
 'Swift, Kotlin, Flutter, React Native, Firebase, Node.js, GraphQL',
 'Mobile App Development Company for iOS & Android | AivraSol',
 'Native and cross-platform iOS and Android apps by AivraSol. Design, development, launch and support. Get a free consultation.', 2),

('service', 'ui-ux-design', 'UI/UX Design & Branding', 'UI/UX', 'pen',
 'Research-led interface design and brand identity that make your product easy to use and easy to remember.',
 'Clear, modern designs that turn visitors into customers and make products easy to use.',
 'Design that people understand at first glance',
 'User Research | Interviews, surveys and analytics reviews to learn what your users really need.\nWireframes and Prototypes | Clickable prototypes so you can test ideas before any code is written.\nWeb UI Design | Responsive website and web app designs that look sharp on every screen.\nMobile UI Design | App screens that follow iOS and Android patterns users already know.\nBrand Identity | Logos, colour palettes, typography and brand guidelines.\nDesign Systems | Reusable component libraries that keep your product consistent as it grows.',
 'Design that drives results',
 'Good design is not just about looks. We test layouts with real users, follow accessibility standards and hand developers clean, organised design files, so what you approve is exactly what gets built.',
 'Figma, Adobe XD, Illustrator, Photoshop, Framer, Maze',
 'UI/UX Design & Branding Agency | AivraSol',
 'User research, UI/UX design, prototypes and brand identity by AivraSol. Designs that are easy to use and convert. Get a free consultation.', 3),

('service', 'cloud-devops', 'Cloud Services (DevOps)', 'Cloud Services', 'cloud',
 'Cloud setup, automated deployments and round-the-clock monitoring that keep your systems fast, secure and cost-efficient.',
 'Reliable cloud infrastructure and automated releases, so your team can ship faster with less risk.',
 'Stable systems, faster releases',
 'Cloud Migration | Move servers and apps to AWS, Azure or Google Cloud with minimal downtime.\nCI/CD Pipelines | Automated build, test and deploy pipelines for safe, frequent releases.\nInfrastructure as Code | Repeatable environments with Terraform and Ansible.\nContainers and Kubernetes | Docker and Kubernetes setups that scale with traffic.\nMonitoring and Alerts | Dashboards, logs and alerts that catch problems before users notice.\nCost Optimisation | Right-sized resources and reserved plans that cut your monthly cloud bill.',
 'Certified cloud engineers',
 'Our DevOps engineers design for security and uptime from the start. We document every environment, automate backups and test recovery plans, so you are never locked in or left guessing.',
 'AWS, Azure, Google Cloud, Docker, Kubernetes, Terraform, GitHub Actions, Jenkins',
 'Cloud & DevOps Services | AivraSol',
 'Cloud migration, CI/CD, Kubernetes, monitoring and cost optimisation by AivraSol DevOps engineers. Get a free consultation.', 4),

('service', 'artificial-intelligence', 'Artificial Intelligence', 'Artificial Intelligence', 'cpu',
 'Practical AI solutions such as chatbots, forecasting and document automation, built on your own data and connected to your existing tools.',
 'Practical AI that saves time, cuts costs and helps you make better decisions.',
 'Turn your data into smart decisions',
 'AI Chatbots and Assistants | Support and sales assistants trained on your own documents and connected to your systems.\nDemand Forecasting | Predict sales, stock levels and demand to reduce waste and avoid shortages.\nDocument Automation | Read invoices, forms and contracts automatically and send the data where it belongs.\nRecommendation Engines | Personalised product and content suggestions that lift sales.\nComputer Vision | Image and video analysis for quality checks, counting and tracking.\nPredictive Maintenance | Spot equipment problems early from sensor data and logs.',
 'Responsible AI engineering',
 'We start with a small proof of concept on your real data, measure the results, and only then scale up. Your data stays private, models are monitored after launch, and you always know how decisions are made.',
 'Python, PyTorch, TensorFlow, LangChain, OpenAI, Hugging Face, scikit-learn',
 'AI Development Services | AivraSol',
 'AI chatbots, forecasting, document automation and computer vision by AivraSol. Practical AI built on your data. Get a free consultation.', 5),

('service', 'seo-digital-marketing', 'SEO & Digital Marketing', 'SEO', 'search',
 'Technical SEO, content and performance marketing that bring the right visitors to your website and turn them into leads.',
 'Get found by the right customers on Google and grow your leads month after month.',
 'Grow your traffic and your leads',
 'SEO Audit | A full technical, content and backlink review with a clear action plan.\nKeyword Research | Find the searches your buyers use and how hard each one is to win.\nOn-Page SEO | Titles, content, internal links and structured data that search engines understand.\nTechnical SEO | Page speed, Core Web Vitals, crawl errors and indexing fixed properly.\nContent Marketing | Helpful articles and landing pages that rank and convert.\nReporting | Monthly reports in plain language showing traffic, rankings and leads.',
 'Clear, measurable growth',
 'We focus on results you can measure: more qualified visitors, more enquiries and lower cost per lead. No vague promises, just honest reporting every month.',
 'Google Search Console, GA4, Ahrefs, Semrush, Screaming Frog, Google Ads',
 'SEO & Digital Marketing Services | AivraSol',
 'SEO audits, technical SEO, content marketing and reporting by AivraSol. Grow your traffic and leads. Get a free consultation.', 6),

('hire', 'devops-engineer', 'Hire DevOps Engineers', 'DevOps Engineer', 'infinity',
 'Experienced DevOps engineers who automate your deployments, harden your cloud and keep your systems online.',
 'Add skilled DevOps engineers to your team in days, not months.',
 'Ship faster with reliable automation',
 'Cloud Expertise | Hands-on experience with AWS, Azure and Google Cloud production systems.\nCI/CD Automation | Pipelines that test and deploy every change safely.\nContainers | Docker and Kubernetes clusters that scale on demand.\nSecurity First | Access control, secrets management and regular patching built in.',
 'Why hire DevOps engineers from AivraSol?',
 'Our engineers join your stand-ups, use your tools and follow your processes. You get senior skills without the cost and delay of local hiring, plus a replacement guarantee if the fit is not right.',
 'AWS, Azure, GCP, Docker, Kubernetes, Terraform, Ansible, Prometheus',
 'Hire DevOps Engineers | AivraSol', 'Hire skilled DevOps engineers from AivraSol for AWS, Azure, Kubernetes and CI/CD. Flexible monthly and hourly plans.', 1),

('hire', 'laravel-developer', 'Hire Laravel Developers', 'Laravel Developer', 'code',
 'Laravel experts who build secure, well-tested PHP applications, APIs and admin panels.',
 'Build robust PHP applications with dedicated Laravel developers.',
 'Clean PHP code that lasts',
 'Laravel Expertise | Deep knowledge of Eloquent, queues, events, Livewire and Laravel ecosystem tools.\nAPI Development | Secure REST and GraphQL APIs for web and mobile apps.\nLegacy Upgrades | Move old PHP or older Laravel versions to the latest release safely.\nTesting | Feature and unit tests with PHPUnit and Pest for confident releases.',
 'Why hire Laravel developers from AivraSol?',
 'Our Laravel developers follow PSR standards, write tests and document their work. They fit into your workflow from day one and you can scale the team up or down each month.',
 'PHP, Laravel, Livewire, MySQL, Redis, Vue, Inertia, Pest',
 'Hire Laravel Developers | AivraSol', 'Hire dedicated Laravel developers from AivraSol for web apps, APIs and upgrades. Flexible monthly and hourly plans.', 2),

('hire', 'python-developer', 'Hire Python Developers', 'Python Developer', 'terminal',
 'Python developers for web backends, data pipelines, automation and AI projects.',
 'Hire Python experts for web, data and AI projects.',
 'Python talent for web, data and AI',
 'Web Backends | Django and FastAPI applications that are fast, secure and well structured.\nData Engineering | ETL pipelines, data cleaning and reporting at scale.\nAutomation | Scripts and bots that remove repetitive manual work.\nAI and Machine Learning | Model training, evaluation and deployment into production.',
 'Why hire Python developers from AivraSol?',
 'Our Python developers combine solid engineering with data skills. They write readable, tested code and communicate clearly, so your project moves forward without surprises.',
 'Python, Django, FastAPI, Flask, Pandas, PostgreSQL, Celery, PyTorch',
 'Hire Python Developers | AivraSol', 'Hire Python developers from AivraSol for Django, FastAPI, data engineering and AI. Flexible monthly and hourly plans.', 3),

('hire', 'reactjs-developer', 'Hire React.js Developers', 'React.js Developer', 'atom',
 'React developers who build fast, accessible and easy-to-maintain user interfaces.',
 'Build modern, fast interfaces with skilled React.js developers.',
 'Interfaces that feel instant',
 'React Expertise | Hooks, context, state management and performance tuning.\nNext.js | Server rendering and static pages for speed and SEO.\nComponent Libraries | Reusable, documented components that keep your UI consistent.\nTesting | Jest and Testing Library suites that catch bugs early.',
 'Why hire React.js developers from AivraSol?',
 'Our React developers care about speed, accessibility and clean structure. They work closely with designers and backend teams to deliver features that look right and work right.',
 'React, Next.js, TypeScript, Redux, React Query, Tailwind CSS, Jest',
 'Hire React.js Developers | AivraSol', 'Hire React.js and Next.js developers from AivraSol for fast, modern web apps. Flexible monthly and hourly plans.', 4),

('hire', 'nodejs-developer', 'Hire Node.js Developers', 'Node.js Developer', 'server',
 'Node.js developers for scalable APIs, real-time apps and microservices.',
 'Scale your backend with dedicated Node.js developers.',
 'Backends built to scale',
 'API Development | REST and GraphQL APIs with Express and NestJS.\nReal-Time Features | Chat, live tracking and notifications with WebSockets.\nMicroservices | Small, independent services that are easy to scale and deploy.\nPerformance | Profiling, caching and query tuning for heavy traffic.',
 'Why hire Node.js developers from AivraSol?',
 'Our Node.js developers write typed, tested and well-documented code. They know how to design APIs that are secure, fast and easy for frontend and mobile teams to use.',
 'Node.js, NestJS, Express, TypeScript, MongoDB, PostgreSQL, Redis, Socket.IO',
 'Hire Node.js Developers | AivraSol', 'Hire Node.js developers from AivraSol for APIs, real-time apps and microservices. Flexible monthly and hourly plans.', 5),

('hire', 'react-native-developer', 'Hire React Native Developers', 'React Native Developer', 'phone',
 'React Native developers who ship polished iOS and Android apps from a single codebase.',
 'One codebase, two platforms, half the effort.',
 'Native feel, shared code',
 'Cross-Platform Apps | One codebase for iOS and Android with native performance.\nNative Modules | Custom native code when your app needs device features.\nApp Store Releases | Build, signing and store submission handled end to end.\nOver-the-Air Updates | Fix bugs fast without waiting for store review.',
 'Why hire React Native developers from AivraSol?',
 'Our React Native developers have shipped apps to both stores and know the details that make an app feel native. You get faster delivery and lower cost without cutting quality.',
 'React Native, Expo, TypeScript, Redux, Firebase, Swift, Kotlin',
 'Hire React Native Developers | AivraSol', 'Hire React Native developers from AivraSol for iOS and Android apps from one codebase. Flexible monthly and hourly plans.', 6);

INSERT INTO projects (slug, title, category, industry, location, summary, challenge, solution, results, tech, image, is_featured, is_sample, sort_order) VALUES
('event-pos-ticketing', 'Event POS & Ticketing System', 'Web App', 'Events', '',
 'A cloud point-of-sale and ticketing platform for busy seasonal events, with RFID cards, payment terminals and live sales reports.',
 'Event organisers needed one system to sell tickets, run food and drink stalls and track stock across many vendors, with no tolerance for downtime on busy nights.',
 'We built a cloud POS with offline mode, RFID wallet cards, card terminal integration and a live dashboard for organisers and vendors.',
 'Faster queues at every stall\nOne live view of sales across all vendors\nWorks even when the venue internet drops',
 'Laravel, Vue, MySQL, Redis, Android POS', 'assets/img/projects/event-pos.svg', 1, 1, 1),
('vpn-mobile-app', 'Privacy VPN App', 'Mobile App', 'Cybersecurity', '',
 'A one-tap VPN app for iOS and Android with server selection, subscriptions and a clean, friendly interface.',
 'The client wanted a VPN that non-technical users could trust and use in one tap, with in-app subscriptions on both stores.',
 'We designed a simple one-button interface, built the app in React Native and connected it to a scalable server network and subscription billing.',
 'One codebase for iOS and Android\nSubscriptions through both app stores\nSimple one-tap connection flow',
 'React Native, Node.js, WireGuard, Stripe, AWS', 'assets/img/projects/vpn-app.svg', 1, 1, 2),
('fashion-ecommerce', 'Fashion E-commerce Store', 'E-commerce', 'Retail', '',
 'An online leather and fashion store with fast product search, size guides and international shipping.',
 'The brand had a large catalogue and many international buyers, but a slow store and a checkout that lost customers.',
 'We rebuilt the store with a faster theme, smarter search and filters, a simpler checkout and multi-currency pricing.',
 'Much faster page loads on mobile\nSimpler three-step checkout\nPrices shown in local currency',
 'WooCommerce, PHP, MySQL, Cloudflare', 'assets/img/projects/fashion-store.svg', 1, 1, 3),
('fitness-supplements-store', 'Fitness Supplements Store', 'E-commerce', 'Health & Fitness', '',
 'A supplements shop with verified products, subscriptions and cash-on-delivery support.',
 'Customers worried about fake supplements and the store needed cash on delivery alongside card payments.',
 'We added verified product badges, batch information, subscriptions for repeat orders and both COD and card checkout.',
 'Clear product trust signals\nRepeat orders through subscriptions\nCash on delivery and card payments',
 'Shopify, Liquid, JavaScript', 'assets/img/projects/supplements.svg', 0, 1, 4),
('flower-delivery-platform', 'Flower Delivery Platform', 'Web App', 'Retail', '',
 'Same-day flower delivery with delivery slots, gift messages and a driver app.',
 'Orders came in by phone and chat, which caused missed deliveries and mixed-up gift messages.',
 'We built an online store with delivery time slots, gift notes and a simple driver app with live order status.',
 'Online ordering with delivery slots\nFewer missed deliveries\nCustomers see live order status',
 'Next.js, Node.js, PostgreSQL, Google Maps API', 'assets/img/projects/flowers.svg', 0, 1, 5),
('equipment-rental-portal', 'Equipment Rental Portal', 'Web App', 'Construction', '',
 'A rental and sales portal for construction equipment with availability calendars and online booking.',
 'Customers had to call to check if a machine was free, and staff tracked bookings in spreadsheets.',
 'We built a catalogue with live availability, online booking requests and an admin panel for staff.',
 'Live availability for every machine\nOnline booking requests\nOne admin panel instead of spreadsheets',
 'Laravel, Livewire, MySQL, Tailwind CSS', 'assets/img/projects/equipment.svg', 0, 1, 6);

INSERT INTO faqs (scope, question, answer, sort_order) VALUES
('general', 'How much does a custom software project cost?', 'It depends on the size and features of your project. Small websites and MVPs cost much less than large enterprise systems. Share your idea through the free consultation form and we will send a clear, fixed quote with no hidden fees.', 1),
('general', 'How long does it take to build an app or website?', 'A business website usually takes 3 to 6 weeks. An MVP app often takes 8 to 12 weeks. Larger systems are planned in phases so you can launch early and keep improving.', 2),
('general', 'Will I own the source code?', 'Yes. Once the project is paid, you own the full source code, designs and documentation.', 3),
('general', 'Do you sign an NDA?', 'Yes. We are happy to sign a non-disclosure agreement before you share any details about your idea.', 4),
('general', 'Do you offer support after launch?', 'Yes. Every project includes free bug fixing after launch, and we offer monthly maintenance plans for updates, monitoring and new features.', 5),
('pricing', 'Is the quote really free?', 'Yes. The consultation and quote are free and you are under no obligation to work with us.', 1),
('pricing', 'How do payments work?', 'Fixed-price projects are paid in milestones as work is delivered. Dedicated teams and hired developers are billed monthly.', 2),
('pricing', 'Can I change the scope later?', 'Yes. We agree any changes in writing with the cost and time impact before starting them, so there are no surprises.', 3),
('pricing', 'Can I start small?', 'Yes. Many clients start with a design sprint or an MVP and grow from there.', 4),
('careers', 'Can I apply if there are no open roles?', 'Yes. Send a general application with your CV. We keep strong profiles on file and contact you when a matching role opens.', 1),
('careers', 'Do you offer internships?', 'Yes. We run internships for students and fresh graduates in development, design and marketing.', 2),
('careers', 'Is remote work possible?', 'Many of our roles offer flexible or hybrid work. Each job post shows its work type.', 3);
